import type { FieldCreateResult, ZohoFieldCreate } from '../entities/field'
import type { ZohoModuleCreate } from '../entities/module'

export interface FieldOptions {
    /** Generated by Zoho from the label when left out. */
    api_name?: string
}

export interface LengthOptions extends FieldOptions {
    length?: number
}

export interface DecimalOptions extends FieldOptions {
    decimal_place?: number
}

export interface TextareaOptions extends FieldOptions {
    size?: 'small' | 'large' | 'rich_text'
}

export interface DoubleOptions extends LengthOptions, DecimalOptions {}

export interface CurrencyOptions extends DoubleOptions {
    rounding_option?: 'normal' | 'round_off' | 'round_up' | 'round_down'
    precision?: number
}

export type PicklistValue = string | { display_value: string; actual_value: string }

export interface PicklistOptions extends FieldOptions {
    values: PicklistValue[]
}

export interface LookupOptions extends FieldOptions {
    /** API name of the module the lookup points to. */
    module: string
    /** Label of the related list shown on the target module; the field label when left out. */
    display_label?: string
}

export interface FieldSchema {
    text(label: string, options?: LengthOptions): void
    textarea(label: string, options?: TextareaOptions): void
    email(label: string, options?: FieldOptions): void
    phone(label: string, options?: LengthOptions): void
    website(label: string, options?: FieldOptions): void
    integer(label: string, options?: LengthOptions): void
    bigint(label: string, options?: LengthOptions): void
    double(label: string, options?: DoubleOptions): void
    percent(label: string, options?: DecimalOptions): void
    currency(label: string, options?: CurrencyOptions): void
    date(label: string, options?: FieldOptions): void
    datetime(label: string, options?: FieldOptions): void
    boolean(label: string, options?: FieldOptions): void
    picklist(label: string, options: PicklistOptions): void
    multiselectpicklist(label: string, options: PicklistOptions): void
    lookup(label: string, options: LookupOptions): void
    userlookup(label: string, options?: FieldOptions): void
}

export type FieldsDeclaration = (schema: FieldSchema) => void

export interface CreateModuleMigration {
    /** Generated by Zoho from `plural_label` when left out. */
    api_name?: string
    singular_label: string
    plural_label: string
    /** Names of the profiles that get the module; only `Administrator` when left out. */
    profiles?: string[]
    fields: FieldsDeclaration
}

export interface UpdateModuleMigration {
    /** API name of the existing module the fields are added to. */
    module: string
    fields: FieldsDeclaration
}

export type MigrationDefinition =
    | { create: CreateModuleMigration; update?: never }
    | { update: UpdateModuleMigration; create?: never }

/** A migration reduced to data: what the run will send, with nothing left to execute. */
export type MigrationDescription =
    | {
          action: 'create'
          module: { api_name?: string; singular_label: string; plural_label: string }
          profiles: string[]
          fields: ZohoFieldCreate[]
      }
    | {
          action: 'update'
          module: { api_name: string }
          fields: ZohoFieldCreate[]
      }

export type MigrationStep =
    | { kind: 'create-module'; module: ZohoModuleCreate }
    /** `module` is null when the run learns the API name only once Zoho has created the module. */
    | { kind: 'create-fields'; module: string | null; fields: ZohoFieldCreate[] }

export interface MigrationPlan {
    steps: MigrationStep[]
}

export interface MigrationCheck {
    conflicts: string[]
    /** Ids of the profiles a new module is given, in the order they were named. */
    profileIds: string[]
}

export interface LoadedMigration {
    definition: MigrationDefinition | null
    problem: string | null
}

/** Everything known about a migration before it runs; any conflict blocks the run. */
export interface PreparedMigration {
    name: string
    description: MigrationDescription | null
    plan: MigrationPlan | null
    conflicts: string[]
}

export type MigrationRunStatus = 'applied' | 'failed' | 'blocked'

/** Planned fields compared by label with what Zoho holds after the run. */
export interface MigrationVerification {
    module: string
    created: string[]
    missing: string[]
}

/** What a run reports as it goes; the CLI prints these, and the web app will read the same stream. */
export type MigrationEvent =
    | { type: 'step-started'; index: number; step: MigrationStep }
    | { type: 'module-created'; id: string; api_name: string }
    | { type: 'field-result'; index: number; field_label: string; result: FieldCreateResult }
    | { type: 'step-finished'; index: number; status: 'success' | 'failed'; error?: string }
    | { type: 'verified'; verification: MigrationVerification }
    | { type: 'artifacts-updated'; module: string }
    | { type: 'finished'; status: MigrationRunStatus; message: string }

export interface MigrationJournalEntry {
    status: 'applied' | 'failed'
    ranAt: string
    error?: string
    moduleId?: string
    /** Ids of the created fields by label. */
    fieldIds: Record<string, string>
}

/** Journal entries of one organization by migration name. */
export type MigrationJournal = Record<string, MigrationJournalEntry>
